        if (line1 == null || line1.isBlank()) {
            return normalizeAddress(ownerDto.getAddress());
        }
        String line2 = normalizeAddress(ownerDto.getAddressLine2());
        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
